typescript.originalService:
class LoanProcessingSystemSystem_AutoGenerated {
  /*find the loan with the provided loan id,
   *if the loan exist and the status is ls open,
   *the loan remain amount payment to pay should be the previous value minus the loan's repayment amount
   **/
  loanPayment(loanid: number): boolean {
    /*Definition Start*/
    let loanList: Loan[] = l({
      logic: () =>
        getRepository(Loan).filter(
          (o: any) =>
            l({
              logic: () => o.LoanID === loanid,
              description: "o.LoanID=loanid",
            }).build().pass,
        ),
      description: "Loan.allInstance()->select(o|o.LoanID=loanid)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => loanList.length === 1,
        description: "loanList.size()=1",
      })
        .and({
          logic: () =>
            loanList.forEach(
              (o: Loan) =>
                l({
                  logic: () => o.Status === LoanStatus.LSOPEN,
                  description: "o.Status=LoanStatus::LSOPEN",
                }).build().pass,
            ),
          description: "loanList->forAll(o:Loan|o.Status=LoanStatus::LSOPEN)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let ob: Loan = l({
      execute: () =>
        getRepository(Loan).find(
          (o: any) =>
            l({
              logic: () => o.LoanID === loanid,
              description: "o.LoanID=loanid",
            }).build().pass,
        ),
      description: "Loan.allInstance()->any(o|o.LoanID=loanid)",
    }).build().pass;
    return l({
      execute: () =>
        (ob.RemainAmountToPay = ob.RemainAmountToPay - ob.RepaymentAmount),
      description:
        "ob.RemainAmountToPay=ob.RemainAmountToPay-ob.RepaymentAmount",
    })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { LoanProcessingSystemSystem_AutoGenerated };

