class LoanProcessingSystemSystem_AutoGenerated {
  /*find the loan with the provided loan id,
   *if the loan exist and the status is ls open,
   *the loan remain amount payment to pay should be the previous value minus the loan's repayment amount
   **/
  loanPayment(loanid: number): boolean {
    /*Definition Start*/
    let loanObj: Loan = l({
      logic: () =>
        getRepository(Loan).find(
          (o: any) =>
            l({
              logic: () => o.LoanID === loanid,
              description: "o.LoanID=loanid",
            }).build().pass,
        ),
      description: "Loan.allInstance()->any(o|o.LoanID=loanid)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(loanObj) === false,
        description: "loanObj.oclIsUndefined()=false",
      })
        .and({
          logic: () => loanObj.Status === LoanStatus.LSOPEN,
          description: "loanObj.Status=LoanStatus::LSOPEN",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () =>
        (loanObj.RemainAmountToPay =
          loanObj.RemainAmountToPay - loanObj.RepaymentAmount),
      description:
        "loanObj.RemainAmountToPay=loanObj.RemainAmountToPay-loanObj.RepaymentAmount",
    })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}

